begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(1);
create function pg_temp.assert_inline(v boolean,msg text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Inline type: %',msg;end if;end $$;
create function pg_temp.deny_inline(statement text) returns void language plpgsql as $$begin begin execute statement;exception when others then return;end;raise exception 'Expected denial: %',statement;end $$;
insert into auth.users(id,email) select ('ba110000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'inline.qa.'||i||'@example.invalid' from generate_series(1,3)i;
insert into public.profiles(id,branch_code,full_name,is_active) select ('ba110000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'DPS','[CONTOH] inline QA '||i,true from generate_series(1,3)i;
insert into public.user_role_assignments(profile_id,branch_code,role_code,grant_reason) select ('ba110000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'DPS',(array['hrga','super_admin','coordinator'])[i],'[CONTOH] transaction test' from generate_series(1,3)i;
select set_config('request.jwt.claim.sub','ba110000-0000-4000-8000-000000000001',true);
set local role authenticated;
select * from public.create_personnel_competency_type('DPS','  [CONTOH]  New Competency QA  ');
select * from public.create_personnel_competency_type('DPS','[contoh] new competency qa');
select pg_temp.assert_inline((select count(*)=1 from public.certificate_types where name='[CONTOH] New Competency QA'),'normalized duplicate reuses existing type');
select pg_temp.assert_inline((select category='personnel' and created_by=auth.uid() from public.certificate_types where name='[CONTOH] New Competency QA'),'personnel category and audited author');
select pg_temp.deny_inline($q$select * from public.create_personnel_competency_type('DPS','x')$q$);
select pg_temp.deny_inline($q$select * from public.create_personnel_competency_type('OTHER','[CONTOH] wrong branch')$q$);
select pg_temp.deny_inline($q$insert into public.certificate_types(code,name,category,branch_code) values('CONTOH_INLINE_DENIED','[CONTOH] forbidden client','client','DPS')$q$);
select set_config('request.jwt.claim.sub','ba110000-0000-4000-8000-000000000003',true);
select pg_temp.deny_inline($q$select * from public.create_personnel_competency_type('DPS','[CONTOH] unauthorized')$q$);
select set_config('request.jwt.claim.sub','ba110000-0000-4000-8000-000000000002',true);
select * from public.create_personnel_competency_type('DPS','[CONTOH] Admin competency QA');
reset role;
select pass('HRGA/admin inline competency creation, case/spacing deduplication, category and branch scope');
select * from finish();
rollback;
